import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.C3idr2hZ.js";const u=JSON.parse('{"title":"Continue a local session in ORC","description":"","frontmatter":{},"headers":[],"relativePath":"docs/session-handoff.md","filePath":"docs/session-handoff.md","lastUpdated":1793898059000}'),i={name:"docs/session-handoff.md"};function n(d,e,r,c,h,l){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="continue-a-local-session-in-orc" tabindex="-1">Continue a local session in ORC <a class="header-anchor" href="#continue-a-local-session-in-orc" aria-label="Permalink to &quot;Continue a local session in ORC&quot;">​</a></h1><p>Use the bundled <code>orc-platform</code> skill&#39;s <code>references/execution.md</code> handoff section with Claude Code or Codex. Within Git authorization, the agent commits and pushes the intended work, verifies the remote SHA, calls <code>session_handoff</code>, and uploads its native conversation. In <strong>Sessions</strong>, the imported session appears as <strong>Ready</strong>. Choose <strong>Resume → Terminal</strong> to continue it.</p><p>The destination project must already exist in ORC with its folder scope pointing to a repository on the selected execution host. Its configured remote must match the reported repository. ORC does not clone arbitrary repository URLs supplied in an upload. SSH mode installs files on the same SSH host/user that runs the resumed agent, including a Docker container reached through an SSH alias. Persist the agent home and repository volumes if sessions must survive container replacement. The host needs Git, the relevant agent CLI and, for remote file operations, Python 3.</p><h2 id="http-contract" tabindex="-1">HTTP contract <a class="header-anchor" href="#http-contract" aria-label="Permalink to &quot;HTTP contract&quot;">​</a></h2><p>All operations are available through the API. MCP exposes one convenience tool: <code>session_handoff</code> forwards the same initiation request over HTTP. The SDK exposes <code>client.handoffs.create</code>, <code>get</code> and <code>prepare</code>.</p><table tabindex="0"><thead><tr><th>Operation</th><th>Endpoint</th><th>Authentication</th></tr></thead><tbody><tr><td>Initiate</td><td><code>POST /api/session-handoffs</code></td><td>Bearer token when an API secret is configured; otherwise open</td></tr><tr><td>Upload</td><td><code>PUT /api/session-handoffs/{id}/upload?token=…</code></td><td>Temporary upload capability</td></tr><tr><td>Inspect</td><td><code>GET /api/session-handoffs/{id}</code></td><td>Bearer token when an API secret is configured; otherwise open</td></tr><tr><td>Retry preparation</td><td><code>POST /api/session-handoffs/{id}/prepare</code></td><td>Bearer token when an API secret is configured; otherwise open</td></tr><tr><td>Resume</td><td><code>POST /api/terminals</code> with <code>live_session_id</code></td><td>Existing terminal authentication and workspace rules</td></tr></tbody></table><p>Initiation accepts <code>project</code> (readable name), <code>agent</code> (<code>claude</code> or <code>codex</code>), native <code>session_id</code> (UUID), <code>source_cwd</code>, <code>repository</code> (credential-free URL), <code>remote</code> (default <code>origin</code>), <code>branch</code>, exact pushed <code>commit</code> (40-character SHA), optional <code>subdirectory</code> (relative repo folder) and optional <code>title</code>.</p><p>The returned upload link expires after 15 minutes and is single-use. It authorizes only that handoff, not inspection, terminal launch or other API calls. Upload a JSON body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;files&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;session.jsonl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;content&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;native JSONL text</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]}</span></span></code></pre></div><p>The full encoded body is limited to 64 MiB and 128 files, including actual streamed bytes regardless of Content-Length. Claude also accepts <code>subagents/agent-*.jsonl</code>. Codex accepts one native rollout. Arbitrary paths, credentials/config and agent SQLite databases are rejected. Native conversation IDs are verified before consuming the link. The skill includes a Python upload helper; no SCP or access to the destination filesystem is required on the source machine.</p><h2 id="destination-state" tabindex="-1">Destination state <a class="header-anchor" href="#destination-state" aria-label="Permalink to &quot;Destination state&quot;">​</a></h2><p>The upload is stored privately on the API machine. Preparation captures the selected execution host, fetches the configured remote branch and requires its tip to equal the reported SHA. A changed branch requires a new handoff. ORC creates:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;destination-repo&gt;/.orc/worktrees/&lt;handoff-id&gt;</span></span></code></pre></div><p>The local branch is <code>orc/handoff/&lt;handoff-id&gt;</code>, tracking the reported remote branch. Git&#39;s local exclusions keep this directory out of the original checkout&#39;s status. ORC preserves existing branches, checkouts and session files. Conversation history is copied into a new native UUID, with structured cwd metadata relocated; historical message/tool text is retained. Custom native storage uses the execution host&#39;s <code>CODEX_HOME</code> or <code>CLAUDE_CONFIG_DIR</code> when set.</p><p>Before the first resume, the terminal API verifies the commit, a clean worktree and the native transcript&#39;s presence. Successful launch marks the handoff <code>resumed</code>; later resumes allow the session&#39;s subsequent edits and commits. Existing running terminals are reused by the standard terminal API. Deleting the ORC project keeps its handoff history and session as unassigned; it does not remove the native files or worktree.</p><h2 id="failures-and-limits" tabindex="-1">Failures and limits <a class="header-anchor" href="#failures-and-limits" aria-label="Permalink to &quot;Failures and limits&quot;">​</a></h2><p>Inspect <code>status</code>, <code>error</code>, <code>cwd</code> and <code>live_session_id</code>. Upload returns the handoff record; <code>status: error</code> means bytes were received but preparation failed. Fix the cause and call the prepare endpoint, without uploading again. Preparation records and bundles survive API restarts. A preparation lease can be recovered after five minutes; a ready handoff is returned unchanged on retry. A consumed or expired link cannot upload again.</p><p>Only Git-tracked state is transported. Ignored files, dependencies, environment variables, processes, external attachments, submodule checkouts and LFS hydration need separate preparation. Destination CLI credentials and configuration remain its own. Standalone Codex child-agent sessions are rejected: hand off their parent instead. Active child-agent processes are not migrated. Keep the source idle during the final snapshot and continue work in the destination once it is ready.</p>',18)])])}const f=t(i,[["render",n]]);export{u as __pageData,f as default};
